def group_tuples(Input):
    groups = {}
    for t in Input:
        first, second = t
        if first in groups:
            groups[first].append(second)
        else:
            groups[first] = [second]

    result = []
    for key in groups:
        new_tuple = (key,) + tuple(groups[key])
        result.append(new_tuple)

    return result

